(456225, 42558, 2764, '<td valign="top">uh oh - this one is goin to suffer on darker monitors.  At first all I noticed was his nose, now I can sort of see his arms.  Dark photos rarely get the score they deserve because of the variation in equipment.</td>', 'uh oh - this one is goin to suffer on darker monitors.  At first all I noticed was his nose, now I can sort of see his arms.  Dark photos rarely get the score they deserve because of the variation in equipment.', '2003-10-20 17:09:33.000000', NULL, 1),
(456229, 42983, 4494, '<td valign="top">Very cool shot.  The green is awesome, and the lighting on the guitarist''s face is good too.</td>', 'Very cool shot.  The green is awesome, and the lighting on the guitarist''s face is good too.', '2003-10-20 17:33:54.000000', NULL, 1),
(456235, 42942, 2764, '<td valign="top">I think it would be better without the nose - try cropping up to the tip pf her nose, her eyes are wonderful and don''t need to compete with er nostrils. oh,and the light is lvley too. 8</td>', 'I think it would be better without the nose - try cropping up to the tip pf her nose, her eyes are wonderful and don''t need to compete with er nostrils. oh,and the light is lvley too. 8', '2003-10-20 17:42:57.000000', NULL, 1),
(456236, 42697, 2764, '<td valign="top">sigh, I have never given so many tens, I hope they ALL win.  this ten is particularly beatutiful</td>', 'sigh, I have never given so many tens, I hope they ALL win.  this ten is particularly beatutiful', '2003-10-20 17:47:02.000000', NULL, 1),
