(456239, 43002, 2764, '<td valign="top">oh NOOOO - another ten!  Someone has got to invent an eleven for this challenge!</td>', 'oh NOOOO - another ten!  Someone has got to invent an eleven for this challenge!', '2003-10-20 17:48:20.000000', NULL, 1),
