INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(456264, 42770, 6536, '<td valign="top">Cute idea. Nice lighting. Good composition. 7.</td>', 'Cute idea. Nice lighting. Good composition. 7.', '2003-10-20 18:43:01.000000', NULL, 1),
(456265, 42558, 6536, '<td valign="top">How did you do this one? Is that a poster behind him? Creative idea. 6.</td>', 'How did you do this one? Is that a poster behind him? Creative idea. 6.', '2003-10-20 18:45:12.000000', NULL, 1),
(456267, 42884, 1379, '<td valign="top">Hey... Did David Blaine take this?  Just kidding....  I love the reflections on the water, and the electric crispness of the bridge.  Postcard perfect!</td>', 'Hey... Did David Blaine take this?  Just kidding....  I love the reflections on the water, and the electric crispness of the bridge.  Postcard perfect!', '2003-10-20 18:45:20.000000', NULL, 1),
(456268, 42519, 6536, '<td valign="top">7.</td>', '7.', '2003-10-20 18:45:51.000000', NULL, 1),
(456269, 42788, 6536, '<td valign="top">Good nightscape. Nice bright colors. Great angle. Good composition. 9.</td>', 'Good nightscape. Nice bright colors. Great angle. Good composition. 9.', '2003-10-20 18:48:15.000000', NULL, 1),
(456271, 42983, 6536, '<td valign="top">Great shot. Nice focus and DOF. Good composition and lighting. Nice bright colors. 10.</td>', 'Great shot. Nice focus and DOF. Good composition and lighting. Nice bright colors. 10.', '2003-10-20 18:49:41.000000', NULL, 1),
(456274, 42537, 6536, '<td valign="top">8.</td>', '8.', '2003-10-20 18:51:05.000000', NULL, 1),
(456277, 42983, 11283, '<td valign="top">Great shot, sharp focus. Excellent!</td>', 'Great shot, sharp focus. Excellent!', '2003-10-20 18:53:42.000000', NULL, 1),
(456279, 42537, 11283, '<td valign="top">Very nice shot and color, only critique would be the off center light pool. Maintaining symmetry would have made this perfect. IMHO.</td>', 'Very nice shot and color, only critique would be the off center light pool. Maintaining symmetry would have made this perfect. IMHO.', '2003-10-20 18:55:41.000000', NULL, 1),
(456282, 42983, 675, '<td valign="top">hell yeah...10</td>', 'hell yeah...10', '2003-10-20 18:59:41.000000', NULL, 1),
(456286, 42871, 11283, '<td valign="top">Looks like MechaGodzilla''s eggs. Nice photo.</td>', 'Looks like MechaGodzilla''s eggs. Nice photo.', '2003-10-20 19:05:43.000000', NULL, 1),
(456289, 42537, 772, '<td valign="top">Lovely lighting :)  Strong composition as well.. = 10</td>', 'Lovely lighting :)  Strong composition as well.. = 10', '2003-10-20 19:15:10.000000', NULL, 1),
(456290, 43011, 772, '<td valign="top">The subject choice here doesn''t create much ''wow'' factor or inspiration of any kind for me.</td>', 'The subject choice here doesn''t create much ''wow'' factor or inspiration of any kind for me.', '2003-10-20 19:15:55.000000', NULL, 1),
(456291, 42877, 772, '<td valign="top">Not a particularly interesting subject choice, IMO.</td>', 'Not a particularly interesting subject choice, IMO.', '2003-10-20 19:16:31.000000', NULL, 1),
(456301, 42286, 11693, '<td valign="top">WEnever get leaves like this in SE Texas.  Your photo is like a postcard!</td>', 'WEnever get leaves like this in SE Texas.  Your photo is like a postcard!', '2003-10-20 19:29:16.000000', NULL, 1),
(456303, 42700, 11283, '<td valign="top">Very nice colors. Looks kinda "Carnavale". Good shot.</td>', 'Very nice colors. Looks kinda "Carnavale". Good shot.', '2003-10-20 19:30:54.000000', NULL, 1),
(456314, 42958, 11283, '<td valign="top">Nice.<br/></td>', 'Nice.', '2003-10-20 19:44:48.000000', NULL, 1),
(456317, 42485, 6999, '<td valign="top">Pretty neat, though not exactly subtle lighting. You''ve over-done the sharpening considerably, in my book - all those jagged lines - though I can appreciate what drove you to it. Not bad stuff though.</td>', 'Pretty neat, though not exactly subtle lighting. You''ve over-done the sharpening considerably, in my book - all those jagged lines - though I can appreciate what drove you to it. Not bad stuff though.', '2003-10-20 19:45:55.000000', NULL, 1),
(456318, 42697, 11923, '<td valign="top">Interesting coloring, really gives the image a unique look.  Focus is great, the lighting enhaces rather than detracts.  Border use is great too.  8</td>', 'Interesting coloring, really gives the image a unique look.  Focus is great, the lighting enhaces rather than detracts.  Border use is great too.  8', '2003-10-20 19:46:16.000000', NULL, 1),
(456320, 42969, 11923, '<td valign="top">Beautiful!  Excellent contrast between hard and soft colors.  I love the silhouette look - light usage is marvelous.  The trees against the sky alone would have been dramatic, but the deer addition makes it superb.  Nice shot!  10</td>', 'Beautiful!  Excellent contrast between hard and soft colors.  I love the silhouette look - light usage is marvelous.  The trees against the sky alone would have been dramatic, but the deer addition makes it superb.  Nice shot!  10', '2003-10-20 19:48:25.000000', NULL, 1),
(456326, 42410, 11923, '<td valign="top">The focus is pretty good - I would''ve liked the first few lines in that first paragraph all to be in focus then start blending out.  I wish the lighting was a bit brighter as well, BUT I do like the fact that it is lighting only a portion of the writing and tapers off.  The subject/composition doesn''t hold my attention very long - I find it a little dry, a little color to spice things up may have helped, maybe a red circle around ''read the rules'' or something similar.  Just an idea.  All in all I gave it a 5</td>', 'The focus is pretty good - I would''ve liked the first few lines in that first paragraph all to be in focus then start blending out.  I wish the lighting was a bit brighter as well, BUT I do like the fact that it is lighting only a portion of the writing and tapers off.  The subject/composition doesn''t hold my attention very long - I find it a little dry, a little color to spice things up may have helped, maybe a red circle around ''read the rules'' or something similar.  Just an idea.  All in all I gave it a 5', '2003-10-20 19:53:24.000000', NULL, 1),
(456329, 43012, 3102, '<td valign="top">Very well executed!  That must have taken a significant amount of planning to pull this off well.</td>', 'Very well executed!  That must have taken a significant amount of planning to pull this off well.', '2003-10-20 19:58:44.000000', NULL, 1),
(456330, 42759, 3102, '<td valign="top">Very nicely thought out!  Very often the best shots are the most simple ones, and this certainly holds true here... although I''m betting that it wasn''t necessarily simple to execute!</td>', 'Very nicely thought out!  Very often the best shots are the most simple ones, and this certainly holds true here... although I''m betting that it wasn''t necessarily simple to execute!', '2003-10-20 19:59:55.000000', NULL, 1),
(456331, 42880, 11923, '<td valign="top">Ahh this is an interesting image!  I like the subject, it garners instant interest.  The direction of the lighting, unfortunately casts shadows on a fair portion of the face, if an opportunity presented itself, I think the face with more light on it might have been worth getting - especially with the spotlight title.  I like the action feel in the photo - it looks as if you caught the person dancing or bowing regally.  I think the photo would be even better if the focus was on the face, it looks like the middle left got the most focus though.  I definitely like the image.  7</td>', 'Ahh this is an interesting image!  I like the subject, it garners instant interest.  The direction of the lighting, unfortunately casts shadows on a fair portion of the face, if an opportunity presented itself, I think the face with more light on it might have been worth getting - especially with the spotlight title.  I like the action feel in the photo - it looks as if you caught the person dancing or bowing regally.  I think the photo would be even better if the focus was on the face, it looks like the middle left got the most focus though.  I definitely like the image.  7', '2003-10-20 20:00:13.000000', NULL, 1),
(456332, 42503, 6999, '<td valign="top">Whilst this IS a beautiful moment you''ve captured, I really think I''d like to see it darker overall - a good two stops shoter exposure, I think - to emphasise the blackness of clouds, and to lessen the blow-out area: it doesn''t really look like an approaching storm, just an approaching bunch of clouds. Good work though, and the light on the fields and trees is excellently caught.</td>', 'Whilst this IS a beautiful moment you''ve captured, I really think I''d like to see it darker overall - a good two stops shoter exposure, I think - to emphasise the blackness of clouds, and to lessen the blow-out area: it doesn''t really look like an approaching storm, just an approaching bunch of clouds. Good work though, and the light on the fields and trees is excellently caught.', '2003-10-20 20:00:27.000000', NULL, 1),
(456333, 42954, 3102, '<td valign="top">Quite a beautiful scene!  I think you did a great job with a very tricky exposure situation.  It would have been hard to make it any lighter overall since the top of the mountain would then get blown out.  Very nice!</td>', 'Quite a beautiful scene!  I think you did a great job with a very tricky exposure situation.  It would have been hard to make it any lighter overall since the top of the mountain would then get blown out.  Very nice!', '2003-10-20 20:00:52.000000', NULL, 1),
(456337, 42884, 3102, '<td valign="top">Great job with the exposure, and a very nice subject!  Very impressive work all around.</td>', 'Great job with the exposure, and a very nice subject!  Very impressive work all around.', '2003-10-20 20:01:30.000000', NULL, 1),
(456339, 42952, 3102, '<td valign="top">This is definitely one of my favorites of the challenge.  The lighting certainly sets a great mood for this one, and that''s what the challenge was all about!</td>', 'This is definitely one of my favorites of the challenge.  The lighting certainly sets a great mood for this one, and that''s what the challenge was all about!', '2003-10-20 20:02:15.000000', NULL, 1),
(456340, 42969, 3102, '<td valign="top">Wow -- a super shot!  You were certainly in the right place at the right time (either that or you happen to own a very convincing cut-out of a deer :)</td>', 'Wow -- a super shot!  You were certainly in the right place at the right time (either that or you happen to own a very convincing cut-out of a deer :)', '2003-10-20 20:03:01.000000', NULL, 1),
(456343, 42914, 11923, '<td valign="top">This is a nice photo, I always like these types.  It has a bit less crispness than others I''ve seen, I''m not sure if getting a strong background focus is easy or difficult in this kind of image (never tried it), but I''ve come to look for that.   6</td>', 'This is a nice photo, I always like these types.  It has a bit less crispness than others I''ve seen, I''m not sure if getting a strong background focus is easy or difficult in this kind of image (never tried it), but I''ve come to look for that.   6', '2003-10-20 20:11:01.000000', NULL, 1),
(456356, 42950, 11923, '<td valign="top">Interesting lighting choices.  I like how the light is diffused through her hair, but there are some harsh shadows on her face from the other light, along her nose and cheek.  I like the fact that she isn''t looking straight into the camera.  Nice solid photo though, I gave a 6.  As an aside, I think it might be worth a try to do a similar set up, but have the shadowed side of her face/body be completely or mostly in shadow, just to see what that might look like.</td>', 'Interesting lighting choices.  I like how the light is diffused through her hair, but there are some harsh shadows on her face from the other light, along her nose and cheek.  I like the fact that she isn''t looking straight into the camera.  Nice solid photo though, I gave a 6.  As an aside, I think it might be worth a try to do a similar set up, but have the shadowed side of her face/body be completely or mostly in shadow, just to see what that might look like.', '2003-10-20 20:20:20.000000', NULL, 1),
(456359, 42928, 11923, '<td valign="top">hehe, yeah she does look to be a little unhappy.  The lighting on the face is good - I wish it was a bit softer, though the emotion being an angry one perhaps a harsher light fits better.  Your model is very photogenic, I like the black &amp; white choice.   I wish there was a bit sharper focus, mostly because of the mood of the piece.  All in all, a great shot.  7</td>', 'hehe, yeah she does look to be a little unhappy.  The lighting on the face is good - I wish it was a bit softer, though the emotion being an angry one perhaps a harsher light fits better.  Your model is very photogenic, I like the black & white choice.   I wish there was a bit sharper focus, mostly because of the mood of the piece.  All in all, a great shot.  7', '2003-10-20 20:22:16.000000', NULL, 1),
(456366, 42991, 11923, '<td valign="top">I like this image, is that plastic in the cups?  The lighting is great, as is the added interest of the colors diffusing through the glasses.  I do find a band of less focus across the middle distracting though.  Not sure if that is because of the shape of the glass, or something else, its my main detractant however.  7</td>', 'I like this image, is that plastic in the cups?  The lighting is great, as is the added interest of the colors diffusing through the glasses.  I do find a band of less focus across the middle distracting though.  Not sure if that is because of the shape of the glass, or something else, its my main detractant however.  7', '2003-10-20 20:24:44.000000', NULL, 1),
(456368, 42539, 11923, '<td valign="top">I like the lighting on the whisps, especially the way it highlights certain ones like miniature lighting bolts.  However, I don''t like the color of the background - I think it competes with the main subjects.  With them being so delicate I think a darker background that would let them stand out more would work better, but that''s just my opinion.  6</td>', 'I like the lighting on the whisps, especially the way it highlights certain ones like miniature lighting bolts.  However, I don''t like the color of the background - I think it competes with the main subjects.  With them being so delicate I think a darker background that would let them stand out more would work better, but that''s just my opinion.  6', '2003-10-20 20:27:16.000000', NULL, 1),
(456369, 42955, 11923, '<td valign="top">Hmm.  I think the subject is interesting, I also like the lighting, gives the whole image depth.  Background color sets the piece off nicely.  Only thing I find myself doing is trying to figure out if there is anything on the face of the object, instead of looking at the image as a whole.  Not sure if that''s a good or bad thing, heh.  I really like it though.  7</td>', 'Hmm.  I think the subject is interesting, I also like the lighting, gives the whole image depth.  Background color sets the piece off nicely.  Only thing I find myself doing is trying to figure out if there is anything on the face of the object, instead of looking at the image as a whole.  Not sure if that''s a good or bad thing, heh.  I really like it though.  7', '2003-10-20 20:29:47.000000', NULL, 1),
(456371, 42805, 11923, '<td valign="top">Wow, I love this image.  I think the lighting on here is perfect, just enough shadow to add mystery.  Fills the space in a nice way, not too overbearing.  It may be ordinary driftwood but it really caught my attention and interest quickly.  I also like the fact that there isn''t a distracting border pulling my eyes away.  Very simple but dramatic piece.  10</td>', 'Wow, I love this image.  I think the lighting on here is perfect, just enough shadow to add mystery.  Fills the space in a nice way, not too overbearing.  It may be ordinary driftwood but it really caught my attention and interest quickly.  I also like the fact that there isn''t a distracting border pulling my eyes away.  Very simple but dramatic piece.  10', '2003-10-20 20:32:20.000000', NULL, 1),
(456372, 42550, 11923, '<td valign="top">The title gives me the impression of someone who has broken up and gone away, and so when looking at the assembled items, they are with the light of things left behind.  With that view, I really light the muted lighting and the arrangement of the items is good.  I particularly like the red and blue coordination.  The items in the surrounds I do find a bit distracting, mainly because I''m trying to figure out what they are, sort of get clues about who they could''ve belonged to - not being able to determine the nature of the items brings me out of the image a bit.  Other than that, I really like the composition and subject.  I hope I''m reading what you wanted folks to get out of it - if not, well it still works for me!  8</td>', 'The title gives me the impression of someone who has broken up and gone away, and so when looking at the assembled items, they are with the light of things left behind.  With that view, I really light the muted lighting and the arrangement of the items is good.  I particularly like the red and blue coordination.  The items in the surrounds I do find a bit distracting, mainly because I''m trying to figure out what they are, sort of get clues about who they could''ve belonged to - not being able to determine the nature of the items brings me out of the image a bit.  Other than that, I really like the composition and subject.  I hope I''m reading what you wanted folks to get out of it - if not, well it still works for me!  8', '2003-10-20 20:37:13.000000', NULL, 1),
(456373, 42902, 11923, '<td valign="top">Hm.. an interesting image.  I can''t tell what it is, but I like the color.  The white is a little glaring, but not so much that it kills the shot.  As a personal preference I would''ve liked a larger field of focus.  Other than that, a nice unique use of light and shot altogether.  7</td>', 'Hm.. an interesting image.  I can''t tell what it is, but I like the color.  The white is a little glaring, but not so much that it kills the shot.  As a personal preference I would''ve liked a larger field of focus.  Other than that, a nice unique use of light and shot altogether.  7', '2003-10-20 20:39:19.000000', NULL, 1),
(456377, 42743, 4871, '<td valign="top">This is one of my favourites. I love the VW for starters, but this is definitely a great perspective shot. The only things I would say is to watch for obtrusive ''extras'' to your photo - ie the leaves and stuff on the driveway, the hose coming off the RH wall. These things distract from your photo. When the challenge is over, I would even consider stamping out the house in the background.</td>', 'This is one of my favourites. I love the VW for starters, but this is definitely a great perspective shot. The only things I would say is to watch for obtrusive ''extras'' to your photo - ie the leaves and stuff on the driveway, the hose coming off the RH wall. These things distract from your photo. When the challenge is over, I would even consider stamping out the house in the background.', '2003-10-20 20:54:14.000000', NULL, 1),
(456382, 42928, 4871, '<td valign="top">I would have preferred to see her LH eye in focus. Also the levels are blown out on the LHS. In any photograph, you should be able to see detail and not have areas that are not visible due to blow-out.</td>', 'I would have preferred to see her LH eye in focus. Also the levels are blown out on the LHS. In any photograph, you should be able to see detail and not have areas that are not visible due to blow-out.', '2003-10-20 20:57:59.000000', NULL, 1),
(456385, 42185, 12857, '<td valign="top">great reflection!!!!  sky a little overexposed for my taste but great subject matter. <br/></td>', 'great reflection!!!!  sky a little overexposed for my taste but great subject matter. ', '2003-10-20 21:00:42.000000', NULL, 1),
(456386, 42995, 4871, '<td valign="top">Very nice! Well spotted. I do like this in sepia - just wondering what it would have looked like in color or B&amp;W. I would be very interested to see these if you have them. Love the rays!!!</td>', 'Very nice! Well spotted. I do like this in sepia - just wondering what it would have looked like in color or B&W. I would be very interested to see these if you have them. Love the rays!!!', '2003-10-20 21:01:14.000000', NULL, 1),
(456388, 43016, 12857, '<td valign="top">beautiful photo! Love the play of light off the wax.<br/>dc</td>', 'beautiful photo! Love the play of light off the wax.dc', '2003-10-20 21:02:44.000000', NULL, 1),
(456389, 42855, 4871, '<td valign="top">This is amazing! The sunset is amazing and the title is very fitting. Well done! I cannot see anything that I would want to see differently in this pic - perfect!!</td>', 'This is amazing! The sunset is amazing and the title is very fitting. Well done! I cannot see anything that I would want to see differently in this pic - perfect!!', '2003-10-20 21:03:24.000000', NULL, 1),
(456391, 42485, 12857, '<td valign="top">AWESOME!!!!!!!!!!!!!!!!!!!!!!!!!! WHAT COLOR!!!!!!!!!!!!!!!!!!!!</td>', 'AWESOME!!!!!!!!!!!!!!!!!!!!!!!!!! WHAT COLOR!!!!!!!!!!!!!!!!!!!!', '2003-10-20 21:04:02.000000', NULL, 1),
(456397, 42286, 12857, '<td valign="top">Great color, had the same idea but did not enter it.  Yours is better anyway!!</td>', 'Great color, had the same idea but did not enter it.  Yours is better anyway!!', '2003-10-20 21:11:00.000000', NULL, 1),
(456399, 42719, 12857, '<td valign="top">Beautiful angle, beautiful child, beautiful light, beautiful photo!</td>', 'Beautiful angle, beautiful child, beautiful light, beautiful photo!', '2003-10-20 21:12:13.000000', NULL, 1),
(456401, 42925, 12857, '<td valign="top">I am so glad I took a better look at this one.  This is awesome!!!!  Great Pjhoto.  I love the reflection of the grid on the leaves.  I love the contrast of the orange lights with the blue grid.  I cant stop looking at it.  Bravo!!!! 10!!<br/></td>', 'I am so glad I took a better look at this one.  This is awesome!!!!  Great Pjhoto.  I love the reflection of the grid on the leaves.  I love the contrast of the orange lights with the blue grid.  I cant stop looking at it.  Bravo!!!! 10!!', '2003-10-20 21:17:59.000000', NULL, 1),
(456403, 43002, 2612, '<td valign="top">The lighting has a very natural early morning look to it, which I like. The branch sticking out of the container appears to be out of focus or soft when compared to the container itself, which seems to take away from the overall composition.</td>', 'The lighting has a very natural early morning look to it, which I like. The branch sticking out of the container appears to be out of focus or soft when compared to the container itself, which seems to take away from the overall composition.', '2003-10-20 21:20:12.000000', NULL, 1),
(456404, 42693, 12857, '<td valign="top">I dont know what this is, but great use of light both inside and outside of the structure.  Good choice to offset the structure.</td>', 'I dont know what this is, but great use of light both inside and outside of the structure.  Good choice to offset the structure.', '2003-10-20 21:21:07.000000', NULL, 1),
(456405, 42770, 12857, '<td valign="top">I love the simplicity of the shot!  SiImple and beautiful!</td>', 'I love the simplicity of the shot!  SiImple and beautiful!', '2003-10-20 21:22:38.000000', NULL, 1),
(456408, 42987, 3306, '<td valign="top">Nice job. A difficult shot to get.</td>', 'Nice job. A difficult shot to get.', '2003-10-20 21:44:38.000000', NULL, 1),
(456409, 42982, 3306, '<td valign="top">Interesting picture. Nice job.</td>', 'Interesting picture. Nice job.', '2003-10-20 21:45:54.000000', NULL, 1),
(456410, 42921, 3306, '<td valign="top">Nice lighting effect.</td>', 'Nice lighting effect.', '2003-10-20 21:46:34.000000', NULL, 1),
(456411, 42852, 3306, '<td valign="top">Colorful. Nice try on a difficult subject.</td>', 'Colorful. Nice try on a difficult subject.', '2003-10-20 21:47:25.000000', NULL, 1),
(456414, 42743, 3306, '<td valign="top">Excellent leading lines and I like the way the subject is enhanced by the lighting.</td>', 'Excellent leading lines and I like the way the subject is enhanced by the lighting.', '2003-10-20 22:50:50.000000', NULL, 1),
(456415, 42435, 3306, '<td valign="top">Nice capture. Definitely satisfies the theme.</td>', 'Nice capture. Definitely satisfies the theme.', '2003-10-20 22:51:38.000000', NULL, 1),
(456416, 42207, 3306, '<td valign="top">Nice setup. I like the backround lighting.</td>', 'Nice setup. I like the backround lighting.', '2003-10-20 22:52:31.000000', NULL, 1),
(456417, 42904, 3306, '<td valign="top">I like the feeling of this picture. I wish it were better focused.</td>', 'I like the feeling of this picture. I wish it were better focused.', '2003-10-20 22:53:10.000000', NULL, 1),
(456418, 42946, 3306, '<td valign="top">Simple and effective.</td>', 'Simple and effective.', '2003-10-20 22:54:05.000000', NULL, 1),
(456422, 42364, 11923, '<td valign="top">This is different.  I like the contrast of the pinkish red color against the black, but it looks pretty ragged, like scribbles which does detract for me.  The reflection? of the red in the trees is distracting a bit too, but that may have been unavoidable.  I like the uniqueness of the image as well.  6</td>', 'This is different.  I like the contrast of the pinkish red color against the black, but it looks pretty ragged, like scribbles which does detract for me.  The reflection? of the red in the trees is distracting a bit too, but that may have been unavoidable.  I like the uniqueness of the image as well.  6', '2003-10-20 23:15:12.000000', NULL, 1),
(456424, 42325, 11923, '<td valign="top">Hrm..  a nice rendition of a light bulb.  I like the vantage point it is taken from, I also like the over all neutral color tone of the image.  I do wish it was larger though, I think detail is lost due to its size - this factor had a negative impact for me.  I like the soft focus on the bulb, giving it a nice glow instead of the regular harshness - I think it also helps make it more interesting than it would be if it was in complete focus.  7</td>', 'Hrm..  a nice rendition of a light bulb.  I like the vantage point it is taken from, I also like the over all neutral color tone of the image.  I do wish it was larger though, I think detail is lost due to its size - this factor had a negative impact for me.  I like the soft focus on the bulb, giving it a nice glow instead of the regular harshness - I think it also helps make it more interesting than it would be if it was in complete focus.  7', '2003-10-20 23:18:39.000000', NULL, 1),
(456425, 42762, 7038, '<td valign="top">I think the background detracts this image most for me.  Good use of thirds and composition, but an uninteresting subject matter for me :(</td>', 'I think the background detracts this image most for me.  Good use of thirds and composition, but an uninteresting subject matter for me :(', '2003-10-20 23:18:40.000000', NULL, 1),
(456427, 42983, 7038, '<td valign="top">Excellent, the emotion of the performer really comes through in this photo.  Excellent compostion and use of light to create the mood. 10</td>', 'Excellent, the emotion of the performer really comes through in this photo.  Excellent compostion and use of light to create the mood. 10', '2003-10-20 23:19:45.000000', NULL, 1),
(456428, 42902, 7038, '<td valign="top">fantastic abstract photo.  Excellent composition and colour.  Can''t really think of any way to improve upon this.  Possibly slightly increase the DOF, but that''s just a suggestion. 10</td>', 'fantastic abstract photo.  Excellent composition and colour.  Can''t really think of any way to improve upon this.  Possibly slightly increase the DOF, but that''s just a suggestion. 10', '2003-10-20 23:22:59.000000', NULL, 1),
(456429, 42844, 11923, '<td valign="top">This I think has a light written all over it, but I think the photo''s interest actually comes from the light on the tree, rather than the tree itself as the tree doesn''t have much of an impact on me as a viewer.  I like the fact that the tree does have great focus in the areas that are lit.  Gave a 5</td>', 'This I think has a light written all over it, but I think the photo''s interest actually comes from the light on the tree, rather than the tree itself as the tree doesn''t have much of an impact on me as a viewer.  I like the fact that the tree does have great focus in the areas that are lit.  Gave a 5', '2003-10-20 23:23:20.000000', NULL, 1),
(456430, 43005, 11923, '<td valign="top">Nice composition, wish the lightbox wasn''t in the photo though.  Also find the bright white lights to be distracting.  I love the warm orange color and then the stark black of the twiggy tree against it.  I also like the reflection on the ground helping to tie the whole composition together.  I think it would be better if it was cropped more at the top, the shadows above the ledge draw the eye up and out of the image.  Great photo!  7</td>', 'Nice composition, wish the lightbox wasn''t in the photo though.  Also find the bright white lights to be distracting.  I love the warm orange color and then the stark black of the twiggy tree against it.  I also like the reflection on the ground helping to tie the whole composition together.  I think it would be better if it was cropped more at the top, the shadows above the ledge draw the eye up and out of the image.  Great photo!  7', '2003-10-20 23:25:54.000000', NULL, 1),
(456432, 42564, 11923, '<td valign="top">I love this image!  I especially like the slightly dark, yellow tone of the photo, plus the waves are give it a wonderful movement.  The sun ball flares on the beach and water are unfortunate, but I think the overall appeal of the image overcomes those slight imperfections.  I can''t fully explain exactly what it is that I like about it that really grabs hold for me, but I gave a 9.</td>', 'I love this image!  I especially like the slightly dark, yellow tone of the photo, plus the waves are give it a wonderful movement.  The sun ball flares on the beach and water are unfortunate, but I think the overall appeal of the image overcomes those slight imperfections.  I can''t fully explain exactly what it is that I like about it that really grabs hold for me, but I gave a 9.', '2003-10-20 23:29:54.000000', NULL, 1),
(456433, 42960, 3306, '<td valign="top">I like the mood.</td>', 'I like the mood.', '2003-10-20 23:29:57.000000', NULL, 1),
(456434, 42895, 3306, '<td valign="top">Really nice colors. Nicely balanced. Very creative.</td>', 'Really nice colors. Nicely balanced. Very creative.', '2003-10-20 23:31:42.000000', NULL, 1),
(456435, 42814, 3306, '<td valign="top">Lovely Autumn scene.</td>', 'Lovely Autumn scene.', '2003-10-20 23:32:10.000000', NULL, 1),
(456436, 42519, 11923, '<td valign="top">Gorgeous color, love the light diffusing through the clouds.  The plane is focused enough that it looks great against the background, and it does give a nice feel to the image.  All that said, I think I would''ve preferred the plane not to be in the photo - I think the play of light on cloud is strong enough to hold its own.  Great capture!  9</td>', 'Gorgeous color, love the light diffusing through the clouds.  The plane is focused enough that it looks great against the background, and it does give a nice feel to the image.  All that said, I think I would''ve preferred the plane not to be in the photo - I think the play of light on cloud is strong enough to hold its own.  Great capture!  9', '2003-10-20 23:32:23.000000', NULL, 1),
(456437, 42286, 3306, '<td valign="top">ah yes, its that time of year. Beautiful colors, interesting lighting.</td>', 'ah yes, its that time of year. Beautiful colors, interesting lighting.', '2003-10-20 23:33:02.000000', NULL, 1),
(456438, 43018, 3306, '<td valign="top">Nice capture. Excellent angle. Colors are outstanding.</td>', 'Nice capture. Excellent angle. Colors are outstanding.', '2003-10-20 23:33:57.000000', NULL, 1),
(456439, 42922, 3306, '<td valign="top">Nice capture, but it seems like you adjusted the natural colors. Maybe too much saturation.</td>', 'Nice capture, but it seems like you adjusted the natural colors. Maybe too much saturation.', '2003-10-20 23:35:45.000000', NULL, 1),
(456440, 42674, 11923, '<td valign="top">I understand the composition of the piece, I like it - especially the different background - not many use that lime green.  Good use of light.  I have to be honest and say I''d like it with only the cat statue though.  The lines of the cat are very regal and sensuous and I would love to just see it in silhouette without the pumpkin face.  7</td>', 'I understand the composition of the piece, I like it - especially the different background - not many use that lime green.  Good use of light.  I have to be honest and say I''d like it with only the cat statue though.  The lines of the cat are very regal and sensuous and I would love to just see it in silhouette without the pumpkin face.  7', '2003-10-20 23:36:17.000000', NULL, 1),
(456441, 42893, 3306, '<td valign="top">Nice idea.</td>', 'Nice idea.', '2003-10-20 23:36:48.000000', NULL, 1),
(456443, 42887, 11769, '<td valign="top">One of my favorites. Hope you get in the top three.10</td>', 'One of my favorites. Hope you get in the top three.10', '2003-10-20 23:37:54.000000', NULL, 1),
(456444, 42161, 3306, '<td valign="top">Very attractive. Eyes and hair seem properly lighted but the skin tones are too light.</td>', 'Very attractive. Eyes and hair seem properly lighted but the skin tones are too light.', '2003-10-20 23:38:01.000000', NULL, 1),
(456445, 42666, 3306, '<td valign="top">Simple and too the point.</td>', 'Simple and too the point.', '2003-10-20 23:38:20.000000', NULL, 1),
(456447, 42880, 3306, '<td valign="top">Interesting picture but the face is slightly out of focus and the backround is distracting.</td>', 'Interesting picture but the face is slightly out of focus and the backround is distracting.', '2003-10-20 23:40:04.000000', NULL, 1),
(456449, 42985, 3306, '<td valign="top">The picture is good. lighting is right on as is the focus and subject. Can''t say that I love it though as this figure has been used many times in many challenges.</td>', 'The picture is good. lighting is right on as is the focus and subject. Can''t say that I love it though as this figure has been used many times in many challenges.', '2003-10-20 23:43:59.000000', NULL, 1),
(456450, 42769, 11923, '<td valign="top">Interesting use of light.  Good focus, I like the position of the guitarist, but I have to say the lighting does kill it for me.  I think this was a purposeful choice, but my personal preference would''ve been the intense light behind him, so it cloaked him from behind, giving that feeling of power radiating around the subject.  In an aside, it looks like half his face came off and the light burst out from inside.. but I''m kind of weird.  :)  Strong image, and I''ve decided it was a conscious light choice, gave a 7 even tho its not my cup of tea, still a gutsy different vein to go in.</td>', 'Interesting use of light.  Good focus, I like the position of the guitarist, but I have to say the lighting does kill it for me.  I think this was a purposeful choice, but my personal preference would''ve been the intense light behind him, so it cloaked him from behind, giving that feeling of power radiating around the subject.  In an aside, it looks like half his face came off and the light burst out from inside.. but I''m kind of weird.  :)  Strong image, and I''ve decided it was a conscious light choice, gave a 7 even tho its not my cup of tea, still a gutsy different vein to go in.', '2003-10-20 23:44:46.000000', NULL, 1),
(456451, 42700, 3306, '<td valign="top">Charming.</td>', 'Charming.', '2003-10-20 23:45:02.000000', NULL, 1),
(456452, 42893, 11769, '<td valign="top">Are you in the wrong Challange? Just kidding.:)) Love it. The tall size makes the image look larger than it is with the shadow moving upwards. I like all that space above, the rectangular shape off at a slight angle. 10!</td>', 'Are you in the wrong Challange? Just kidding.:)) Love it. The tall size makes the image look larger than it is with the shadow moving upwards. I like all that space above, the rectangular shape off at a slight angle. 10!', '2003-10-20 23:45:49.000000', NULL, 1),
(456453, 42762, 11769, '<td valign="top">10- Not a thing more need be said.</td>', '10- Not a thing more need be said.', '2003-10-20 23:46:37.000000', NULL, 1),
(456454, 42839, 11923, '<td valign="top">Heh, from the title I expected to see some blossoms, but I like the tack you took with this.  Great light usage, really like the vividness of the green.  This type of image always goes well with black background.  A rather simple subject, beautifully portrayed.  9.</td>', 'Heh, from the title I expected to see some blossoms, but I like the tack you took with this.  Great light usage, really like the vividness of the green.  This type of image always goes well with black background.  A rather simple subject, beautifully portrayed.  9.', '2003-10-20 23:46:55.000000', NULL, 1),
(456455, 43017, 3306, '<td valign="top">Nice lighting and subject. Seems a little grainy.</td>', 'Nice lighting and subject. Seems a little grainy.', '2003-10-20 23:47:06.000000', NULL, 1),
(456456, 42921, 11769, '<td valign="top">A wonderful feeling to that face. Very good comp. Perfect.10</td>', 'A wonderful feeling to that face. Very good comp. Perfect.10', '2003-10-20 23:47:48.000000', NULL, 1),
(456457, 42438, 11769, '<td valign="top">Lovely.10</td>', 'Lovely.10', '2003-10-20 23:48:15.000000', NULL, 1),
(456458, 42607, 11769, '<td valign="top">Nice. 9</td>', 'Nice. 9', '2003-10-20 23:48:57.000000', NULL, 1),
(456461, 42918, 3306, '<td valign="top">Very well done. Excellent focus. Nicely balanced.</td>', 'Very well done. Excellent focus. Nicely balanced.', '2003-10-20 23:49:41.000000', NULL, 1),
(456462, 43012, 11769, '<td valign="top">Evil lurks..9</td>', 'Evil lurks..9', '2003-10-20 23:49:48.000000', NULL, 1),
(456463, 42558, 11769, '<td valign="top">Very creative. Warrants a 9</td>', 'Very creative. Warrants a 9', '2003-10-20 23:51:25.000000', NULL, 1),
(456465, 42990, 11923, '<td valign="top">Hm.. I''m not sure why, but the rose looks digitized or pixelly to me, maybe its the focus or the lighting.  I like the concept of the piece (as gathered by the title) but I don''t think I''m following how the image portrays what the title says.  Maybe its because the light source is in the photo and so I can''t visually grasp how it is faded.  I think just having the soft glow of the candle light on the rose all on a black background might have been interesting to try.  I do like the choice in lighting, candlelight and roses always go great together in my opinion.  5</td>', 'Hm.. I''m not sure why, but the rose looks digitized or pixelly to me, maybe its the focus or the lighting.  I like the concept of the piece (as gathered by the title) but I don''t think I''m following how the image portrays what the title says.  Maybe its because the light source is in the photo and so I can''t visually grasp how it is faded.  I think just having the soft glow of the candle light on the rose all on a black background might have been interesting to try.  I do like the choice in lighting, candlelight and roses always go great together in my opinion.  5', '2003-10-20 23:52:49.000000', NULL, 1),
(456466, 42844, 3306, '<td valign="top">Nice try but seems a little out of focus and too dark.</td>', 'Nice try but seems a little out of focus and too dark.', '2003-10-20 23:53:16.000000', NULL, 1),
(456467, 42503, 11769, '<td valign="top">What a wonderful place to live. Like a 19th century painting. Good luck.9</td>', 'What a wonderful place to live. Like a 19th century painting. Good luck.9', '2003-10-20 23:53:35.000000', NULL, 1),
(456468, 42438, 3306, '<td valign="top">Very nicely done.</td>', 'Very nicely done.', '2003-10-20 23:53:48.000000', NULL, 1),
(456469, 42537, 11923, '<td valign="top">Very classy photo.  The colors are fantastic, use of light is wonderful.  Crisp focus, good cropping, even the border works well.   My only personal negative is the tray its on.  I think I might like it better sitting on plain black - or even the bottom portion of the stem and foot disappearing into the black, being rendered invisible.  Very dramatic image to my mind.  9</td>', 'Very classy photo.  The colors are fantastic, use of light is wonderful.  Crisp focus, good cropping, even the border works well.   My only personal negative is the tray its on.  I think I might like it better sitting on plain black - or even the bottom portion of the stem and foot disappearing into the black, being rendered invisible.  Very dramatic image to my mind.  9', '2003-10-20 23:55:37.000000', NULL, 1),
(456472, 42591, 11923, '<td valign="top">Very nice!  I really like the use of light in this photo.  Simple but elegant, great focus, nice color.  I think I''d prefer the fencing or net being shadowed on the fronds not to be there, but it works well this way too.  Nice capture.  7</td>', 'Very nice!  I really like the use of light in this photo.  Simple but elegant, great focus, nice color.  I think I''d prefer the fencing or net being shadowed on the fronds not to be there, but it works well this way too.  Nice capture.  7', '2003-10-20 23:58:36.000000', NULL, 1),
(456473, 42719, 11769, '<td valign="top">I first gave you a 7. Then an 8. Now I think only a 10 is good enough. Her expression, and it fits the frame so perfectly. That left hand convinced me. 10         Hope you Ribbon.</td>', 'I first gave you a 7. Then an 8. Now I think only a 10 is good enough. Her expression, and it fits the frame so perfectly. That left hand convinced me. 10         Hope you Ribbon.', '2003-10-20 23:59:04.000000', NULL, 1),
(456474, 42773, 11923, '<td valign="top">Oh how lovely!  I very much like this photo.  I love the way it all works together with the water droplets and whatever is shimmering in the background.  I do wish the other greenery that''s unfocused in the back wasn''t there at all, but still what a great image!  Good color and I get a nice feeling of delicacy.  Very well thoughtout and composed.  10.</td>', 'Oh how lovely!  I very much like this photo.  I love the way it all works together with the water droplets and whatever is shimmering in the background.  I do wish the other greenery that''s unfocused in the back wasn''t there at all, but still what a great image!  Good color and I get a nice feeling of delicacy.  Very well thoughtout and composed.  10.', '2003-10-21 00:01:02.000000', NULL, 1),
(456475, 43014, 11769, '<td valign="top">Well you can''t have mine. But you can have a 10.</td>', 'Well you can''t have mine. But you can have a 10.', '2003-10-21 00:01:15.000000', NULL, 1),
(456477, 42677, 13395, '<td valign="top">i love kitties</td>', 'i love kitties', '2003-10-21 00:04:25.000000', NULL, 1),
(456478, 42822, 11923, '<td valign="top">Fantastic!  I love the use of light in this image, it has a very light, fantasy feel to it.  The sky is beautiful.  This is a reflection on water yes?  If so, it is a great capture (even if it isn''t!).  This is one of my favorite images so far.  There really isn''t anything I don''t like.  I wish I could shoot like this.  :)   10</td>', 'Fantastic!  I love the use of light in this image, it has a very light, fantasy feel to it.  The sky is beautiful.  This is a reflection on water yes?  If so, it is a great capture (even if it isn''t!).  This is one of my favorite images so far.  There really isn''t anything I don''t like.  I wish I could shoot like this.  :)   10', '2003-10-21 00:04:50.000000', NULL, 1),
(456485, 42985, 12661, '<td valign="top">I hope you are John and I hope there will be a print available.  I was considering ordering the ''In The Beginning'' print. If this becomes available, I\''ll order both and hang them together. Somehow you manage to bring life to little wood manekins. Have you considered changing your handle to ''Gepetto''?</td>', 'I hope you are John and I hope there will be a print available.  I was considering ordering the ''In The Beginning'' print. If this becomes available, I\''ll order both and hang them together. Somehow you manage to bring life to little wood manekins. Have you considered changing your handle to ''Gepetto''?', '2003-10-21 00:12:44.000000', NULL, 1),
(456492, 42539, 7969, '<td valign="top">i love the softness and background colors in this shot, the fine ''hairs'', good composition. Very nice work.</td>', 'i love the softness and background colors in this shot, the fine ''hairs'', good composition. Very nice work.', '2003-10-21 00:30:59.000000', NULL, 1),
(456493, 42969, 7969, '<td valign="top">I love the shadowed effect of your shot.  The composition is wonderful, as is the fog over the horizon.  Very pleasing shot, well done.</td>', 'I love the shadowed effect of your shot.  The composition is wonderful, as is the fog over the horizon.  Very pleasing shot, well done.', '2003-10-21 00:33:01.000000', NULL, 1),
(456494, 42700, 7969, '<td valign="top">This is a great image, it has a painting like quality to it.  She certainly does not look comfortable but the lighting is excellent.  Very well done.</td>', 'This is a great image, it has a painting like quality to it.  She certainly does not look comfortable but the lighting is excellent.  Very well done.', '2003-10-21 00:37:04.000000', NULL, 1),
(456497, 42693, 7969, '<td valign="top">The light coming over the building is great, I feel like i would somehow like more of the light and less of the building.</td>', 'The light coming over the building is great, I feel like i would somehow like more of the light and less of the building.', '2003-10-21 00:39:18.000000', NULL, 1),
(456501, 42485, 7969, '<td valign="top">I like the monotone choice for your shot.  Would be curious to see an outtake without the plants but i still like your choice.  I like the shadowy feel of it too.</td>', 'I like the monotone choice for your shot.  Would be curious to see an outtake without the plants but i still like your choice.  I like the shadowy feel of it too.', '2003-10-21 00:42:58.000000', NULL, 1),
(456503, 42773, 7969, '<td valign="top">This seems familiar,  great shot. The light on it is wonderful.</td>', 'This seems familiar,  great shot. The light on it is wonderful.', '2003-10-21 00:43:20.000000', NULL, 1),
(456504, 43012, 10084, '<td valign="top">This shot gives a great feeling of autumn. The lighting on the pumpkin give you a sense of the shape of it.  From light to dark. The shadow casting of the jack o'' lantern face is good. It would be nice to have a stronger image or a different colored background, yet it''s such a nice shot.</td>', 'This shot gives a great feeling of autumn. The lighting on the pumpkin give you a sense of the shape of it.  From light to dark. The shadow casting of the jack o'' lantern face is good. It would be nice to have a stronger image or a different colored background, yet it''s such a nice shot.', '2003-10-21 00:44:55.000000', NULL, 1),
(456505, 42759, 7969, '<td valign="top">I like the strk contrast of the black and white, yet with the soft shodow.  I really like the angle of the line running thru this too, nice simpe yet pleasing shot.  Well done.</td>', 'I like the strk contrast of the black and white, yet with the soft shodow.  I really like the angle of the line running thru this too, nice simpe yet pleasing shot.  Well done.', '2003-10-21 00:45:02.000000', NULL, 1),
(456508, 42948, 7969, '<td valign="top">You have achieved a feeling of ''wondering who''s there'' with your light, so I think this is very successful shot from an emotive point of view. Nicely done.</td>', 'You have achieved a feeling of ''wondering who''s there'' with your light, so I think this is very successful shot from an emotive point of view. Nicely done.', '2003-10-21 00:46:43.000000', NULL, 1),
(456511, 42383, 7969, '<td valign="top">I like the soft feel of your shot, good angle and lighting on the side of the building.</td>', 'I like the soft feel of your shot, good angle and lighting on the side of the building.', '2003-10-21 00:48:02.000000', NULL, 1),
(456513, 42946, 10084, '<td valign="top">Beautiful beams of bluish hued ray of light coming through the shutters. Very dramatic. Makes you wonder what awaits you behind the doors. The bold shadows helps to make a bold statement.  Great use of light.</td>', 'Beautiful beams of bluish hued ray of light coming through the shutters. Very dramatic. Makes you wonder what awaits you behind the doors. The bold shadows helps to make a bold statement.  Great use of light.', '2003-10-21 00:49:35.000000', NULL, 1),
(456514, 42719, 7969, '<td valign="top">I like the grainy feel and the perspective of this shot.  Not too mention the girl is cute, but this shot does have more to it than just a cute kid.  She really does communicate an aspiration and longing.  Very well done.</td>', 'I like the grainy feel and the perspective of this shot.  Not too mention the girl is cute, but this shot does have more to it than just a cute kid.  She really does communicate an aspiration and longing.  Very well done.', '2003-10-21 00:51:31.000000', NULL, 1),
(456517, 42991, 7969, '<td valign="top">Clever and creative interpretation of challenge.  Technically well done too. What is that in the glasses?  Fog? Ice?   hmm do tell  :  )</td>', 'Clever and creative interpretation of challenge.  Technically well done too. What is that in the glasses?  Fog? Ice?   hmm do tell  :  )', '2003-10-21 00:53:27.000000', NULL, 1),
(456518, 42286, 7969, '<td valign="top">I lament, i have been taking lots of leaves lately, and I must say I really like how you captured these, the light IS very nice.  It is consistent with the warmth of the fall colours.  Nicely done.</td>', 'I lament, i have been taking lots of leaves lately, and I must say I really like how you captured these, the light IS very nice.  It is consistent with the warmth of the fall colours.  Nicely done.', '2003-10-21 00:56:10.000000', NULL, 1),
(456519, 42666, 11800, '<td valign="top">Hot. Love the colors. Grain enhances the mood. Too much usm, however.</td>', 'Hot. Love the colors. Grain enhances the mood. Too much usm, however.', '2003-10-21 00:56:13.000000', NULL, 1),
(456520, 42674, 10084, '<td valign="top">Very nice silhouettes. I like the great highlights on the curves of the cat.  The Jack O'' Lantern also helps to give a sense of Halloween. I don''t know if I really like the lime green background, it''s what drew me to the thumbnail. Maybe an orange or more of an autumn color would work better.</td>', 'Very nice silhouettes. I like the great highlights on the curves of the cat.  The Jack O'' Lantern also helps to give a sense of Halloween. I don''t know if I really like the lime green background, it''s what drew me to the thumbnail. Maybe an orange or more of an autumn color would work better.', '2003-10-21 00:56:19.000000', NULL, 1),
(456521, 42954, 7969, '<td valign="top">Beautiful spot.  Can you give me directions how to get there??  :  )</td>', 'Beautiful spot.  Can you give me directions how to get there??  :  )', '2003-10-21 00:56:59.000000', NULL, 1),
(456524, 42948, 8816, '<td valign="top">Strange, this is complete deja vu, I did almost an exact replica of this for the Freedom challenge.  NICE IDEA lol!  Might have looked better in B&amp;W, wish I could''ve used mine in this challenge!  Nice job!  Mine is in my portfolio under challenge entries if you wanna take a look!</td>', 'Strange, this is complete deja vu, I did almost an exact replica of this for the Freedom challenge.  NICE IDEA lol!  Might have looked better in B&W, wish I could''ve used mine in this challenge!  Nice job!  Mine is in my portfolio under challenge entries if you wanna take a look!', '2003-10-21 01:03:17.000000', NULL, 1),
(456526, 42884, 7969, '<td valign="top">I like the sharpness of this shot, I also like the calm and reflections of the water.  Well done.</td>', 'I like the sharpness of this shot, I also like the calm and reflections of the water.  Well done.', '2003-10-21 01:04:21.000000', NULL, 1),
(456528, 42958, 11800, '<td valign="top">The set up, composition and color is great. I can see his nose and face just enough to see he is looking down. Somehow, that takes away from the mood.</td>', 'The set up, composition and color is great. I can see his nose and face just enough to see he is looking down. Somehow, that takes away from the mood.', '2003-10-21 01:05:28.000000', NULL, 1),
(456530, 43016, 11800, '<td valign="top">Disturbling sexual. Ah. But I love those cars. 9</td>', 'Disturbling sexual. Ah. But I love those cars. 9', '2003-10-21 01:06:42.000000', NULL, 1),
(456566, 42986, 12902, '<td valign="top">The colours are amazing. Here is the essence of fire, the essence of the sun. Great idea for a competition called "Lighting".</td>', 'The colours are amazing. Here is the essence of fire, the essence of the sun. Great idea for a competition called "Lighting".', '2003-10-21 02:46:08.000000', NULL, 1),
(456571, 42814, 9441, '<td valign="top">Beautiful color hues, wonderful texture and detail...I like the composition and cropping....nice job!</td>', 'Beautiful color hues, wonderful texture and detail...I like the composition and cropping....nice job!', '2003-10-21 03:26:53.000000', NULL, 1),
(456576, 42207, 9441, '<td valign="top">the background is awesome...such a wonderful softness to this photo.</td>', 'the background is awesome...such a wonderful softness to this photo.', '2003-10-21 03:41:51.000000', NULL, 1),
(456597, 42958, 10084, '<td valign="top">Lighting is very creepy. Great Halloween themed shot. I like how the center part of the shot is really bright and gets darker as you get toward the foreground. The silhouette is pretty scary. The use of the red adds to this feeling.</td>', 'Lighting is very creepy. Great Halloween themed shot. I like how the center part of the shot is really bright and gets darker as you get toward the foreground. The silhouette is pretty scary. The use of the red adds to this feeling.', '2003-10-21 04:28:44.000000', NULL, 1),
(456598, 42994, 10084, '<td valign="top">Very interesting composition. I like the layering effect that you achieved. The orange, green ,the white and then the blue. Great eye on seeing this one.</td>', 'Very interesting composition. I like the layering effect that you achieved. The orange, green ,the white and then the blue. Great eye on seeing this one.', '2003-10-21 04:30:58.000000', NULL, 1),
(456599, 42960, 10084, '<td valign="top">Beautiful lighting in your composition. I like how the foreground with the bottle and the glasses is really dark and the background where the shadows are cast is really lit and bright. Great contrasting. The window and the brightness helps to bring the wine bottle and glasses out of the picture.</td>', 'Beautiful lighting in your composition. I like how the foreground with the bottle and the glasses is really dark and the background where the shadows are cast is really lit and bright. Great contrasting. The window and the brightness helps to bring the wine bottle and glasses out of the picture.', '2003-10-21 04:33:32.000000', NULL, 1),
(456601, 42325, 10084, '<td valign="top">The composition is very interesting. A lot of neat circular shapes. Good contrast brings out the blacks.</td>', 'The composition is very interesting. A lot of neat circular shapes. Good contrast brings out the blacks.', '2003-10-21 04:43:07.000000', NULL, 1),
(456602, 42591, 10084, '<td valign="top">Beautiful patterns in the palm leaves. The lighting really helps bring out the fine fibers of the leaves. Really nice contrast from the left to the right.</td>', 'Beautiful patterns in the palm leaves. The lighting really helps bring out the fine fibers of the leaves. Really nice contrast from the left to the right.', '2003-10-21 04:45:19.000000', NULL, 1),
(456603, 42364, 10084, '<td valign="top">Very cool effect. I''m assuming that you took a longer exposure and used a laser. Very nice. I think that the shot would look nicer without the red border.</td>', 'Very cool effect. I''m assuming that you took a longer exposure and used a laser. Very nice. I think that the shot would look nicer without the red border.', '2003-10-21 04:48:05.000000', NULL, 1),
(456619, 42483, 13364, '<td valign="top">Vá hvað þetta er mikil snilld hjá þér Bjöggi! Kv. Halla</td>', 'Vá hvað þetta er mikil snilld hjá þér Bjöggi! Kv. Halla', '2003-10-21 07:42:05.000000', NULL, 1),
(456622, 42952, 7304, '<td valign="top">Nice silhouette and use of light. The red really sets it off. Nice form for the martial artist. Karate?</td>', 'Nice silhouette and use of light. The red really sets it off. Nice form for the martial artist. Karate?', '2003-10-21 07:44:16.000000', NULL, 1),
(456623, 42788, 7304, '<td valign="top">The neon glow is great. The angle really makes this shot work and makes it more interesting. Great use of light.</td>', 'The neon glow is great. The angle really makes this shot work and makes it more interesting. Great use of light.', '2003-10-21 07:45:28.000000', NULL, 1),
(456624, 42969, 7304, '<td valign="top">Nice capture. The light is very soft in the background and that helps set off the foeground much better.</td>', 'Nice capture. The light is very soft in the background and that helps set off the foeground much better.', '2003-10-21 07:46:44.000000', NULL, 1),
(456625, 43012, 7304, '<td valign="top">Cooluse of the light. This is fun.</td>', 'Cooluse of the light. This is fun.', '2003-10-21 07:47:33.000000', NULL, 1),
(456626, 42958, 7304, '<td valign="top">This photo screams evil. Could be a bad nightmare or reality. Good use of light.</td>', 'This photo screams evil. Could be a bad nightmare or reality. Good use of light.', '2003-10-21 07:49:12.000000', NULL, 1),
(456627, 42693, 7304, '<td valign="top">I like the idea and the light is real interesting but it almost need something else. I keep expecting a hand to rise out from behind the image. I gave a 5.</td>', 'I like the idea and the light is real interesting but it almost need something else. I keep expecting a hand to rise out from behind the image. I gave a 5.', '2003-10-21 07:53:14.000000', NULL, 1),
(456629, 42087, 7304, '<td valign="top">Interesting image and use of light. If you don''t read the title the image is hard to determine.</td>', 'Interesting image and use of light. If you don''t read the title the image is hard to determine.', '2003-10-21 07:54:55.000000', NULL, 1),
(456632, 42815, 5728, '<td valign="top">I gotta say this has taken first position in my favourites for this challenge. The combination of glass, color and light will always go down well at DPC, and you can be sure you''ll be way up the top with this pic.</td>', 'I gotta say this has taken first position in my favourites for this challenge. The combination of glass, color and light will always go down well at DPC, and you can be sure you''ll be way up the top with this pic.', '2003-10-21 08:10:50.000000', NULL, 1),
(456633, 42700, 5728, '<td valign="top">Top lighting here. The pose is interesting, kind of as if your subject is flowing through the frame from bottom right to the top left. The gaze out of the frame is very fitting, it finished of the flow somehow. The grain works as well. I''m going to give this a (9).<br/> <br/>Update: I didn''t give any tens in this challenge so this is at the top of my favourites for "lighting"</td>', 'Top lighting here. The pose is interesting, kind of as if your subject is flowing through the frame from bottom right to the top left. The gaze out of the frame is very fitting, it finished of the flow somehow. The grain works as well. I''m going to give this a (9). Update: I didn''t give any tens in this challenge so this is at the top of my favourites for "lighting"', '2003-10-21 08:17:28.000000', NULL, 1),
(456638, 42876, 6202, '<td valign="top">COuld have just a little more contrast of brightness the piece of equipment gets lost in the shadows.  Would love to see more of it.</td>', 'COuld have just a little more contrast of brightness the piece of equipment gets lost in the shadows.  Would love to see more of it.', '2003-10-21 08:30:16.000000', NULL, 1),
(456641, 42895, 6202, '<td valign="top">I really like that background.</td>', 'I really like that background.', '2003-10-21 08:38:22.000000', NULL, 1),
(456649, 42958, 6624, '<td valign="top">for me the axe is a bit too much but the image is good, lighting fits the challenge in establishing the mood 8</td>', 'for me the axe is a bit too much but the image is good, lighting fits the challenge in establishing the mood 8', '2003-10-21 08:58:47.000000', NULL, 1),
(456650, 42537, 7014, '<td valign="top">Good work with light, well done.</td>', 'Good work with light, well done.', '2003-10-21 08:59:04.000000', NULL, 1),
(456652, 43002, 5728, '<td valign="top">Refreshing play of light and shadows. The image composition is also original and together with the color tones make for a top pic - 9.</td>', 'Refreshing play of light and shadows. The image composition is also original and together with the color tones make for a top pic - 9.', '2003-10-21 09:04:08.000000', NULL, 1),
(456653, 42952, 5728, '<td valign="top">Red and black is always a good composition.  Nice sharp silohuette you managed there, good one - 9.</td>', 'Red and black is always a good composition.  Nice sharp silohuette you managed there, good one - 9.', '2003-10-21 09:06:06.000000', NULL, 1),
(456654, 42983, 5728, '<td valign="top">Top three placing in my opinion. The angle you took this pic is awesome, love it. The green and yellow tones really kick this image, yup!</td>', 'Top three placing in my opinion. The angle you took this pic is awesome, love it. The green and yellow tones really kick this image, yup!', '2003-10-21 09:07:36.000000', NULL, 1),
(456656, 42921, 5728, '<td valign="top">Jacko my man! I do recognise this pumpkin so who else could it be? Unless of course you lent it to your brother :-) Choice image as usual.</td>', 'Jacko my man! I do recognise this pumpkin so who else could it be? Unless of course you lent it to your brother :-) Choice image as usual.', '2003-10-21 09:10:06.000000', NULL, 1),
(456657, 42816, 5728, '<td valign="top">Yeah thanks for blinding me there :-) Well I gotta say one thing, this pic has the brightest light of the challenge.</td>', 'Yeah thanks for blinding me there :-) Well I gotta say one thing, this pic has the brightest light of the challenge.', '2003-10-21 09:11:27.000000', NULL, 1),
(456658, 42950, 5728, '<td valign="top">Nice how the sun plays with her hair, very effective. The whole image comes over a little on the soft side though. I think the eyes could be a little sharper.</td>', 'Nice how the sun plays with her hair, very effective. The whole image comes over a little on the soft side though. I think the eyes could be a little sharper.', '2003-10-21 09:12:39.000000', NULL, 1),
(456662, 43018, 11693, '<td valign="top">What a great shot.  I love the composition with the diagonal of the balloon.  Colors and light are vivid.</td>', 'What a great shot.  I love the composition with the diagonal of the balloon.  Colors and light are vivid.', '2003-10-21 09:24:14.000000', NULL, 1),
(456663, 43001, 11693, '<td valign="top">My entry was morning and yours evening andcaptured that same rich deep color those times of day produce.  I love the deep blue and the sun peeking through.  Good shot.</td>', 'My entry was morning and yours evening andcaptured that same rich deep color those times of day produce.  I love the deep blue and the sun peeking through.  Good shot.', '2003-10-21 09:25:56.000000', NULL, 1),
(456665, 42539, 11693, '<td valign="top">What a great macro shot.  The detail is great and the light from behind adds to that.</td>', 'What a great macro shot.  The detail is great and the light from behind adds to that.', '2003-10-21 09:27:13.000000', NULL, 1),
(456667, 42969, 11693, '<td valign="top">You caught the mood perfectly.  Back light is great.</td>', 'You caught the mood perfectly.  Back light is great.', '2003-10-21 09:28:38.000000', NULL, 1),
(456668, 42693, 11693, '<td valign="top">The light streaming and the star trails make this a bold shot.  The warmth of the light in the building says safe and protected.</td>', 'The light streaming and the star trails make this a bold shot.  The warmth of the light in the building says safe and protected.', '2003-10-21 09:30:13.000000', NULL, 1),
(456669, 42993, 11693, '<td valign="top">Repetition here makes a great photo.  The color stays saturated even as the exposure chages closer to the light source.  Often the exposure goes white as it get closer.  This as a good capture.</td>', 'Repetition here makes a great photo.  The color stays saturated even as the exposure chages closer to the light source.  Often the exposure goes white as it get closer.  This as a good capture.', '2003-10-21 09:31:39.000000', NULL, 1),
(456670, 42383, 11693, '<td valign="top">I love lighthouses and it so meets the challenge.  It might be better using the rule of thirds.  It is a little too centered for my humble taste.  Great shot.</td>', 'I love lighthouses and it so meets the challenge.  It might be better using the rule of thirds.  It is a little too centered for my humble taste.  Great shot.', '2003-10-21 09:32:36.000000', NULL, 1),
(456671, 42884, 11693, '<td valign="top">The detail and focus make this shot.  I assume you used a tripod for a long exposure.  It worked.  Good shot.  Wish I could see the bridge in person.</td>', 'The detail and focus make this shot.  I assume you used a tripod for a long exposure.  It worked.  Good shot.  Wish I could see the bridge in person.', '2003-10-21 09:33:55.000000', NULL, 1),
(456672, 42700, 4388, '<td valign="top">the lighting looks a little greenish in the midtones and shadow areas.</td>', 'the lighting looks a little greenish in the midtones and shadow areas.', '2003-10-21 09:34:46.000000', NULL, 1),
(456673, 42677, 11693, '<td valign="top">I don''t usually like cat shots, but this is a really great one.  The detail and focus are amazing.</td>', 'I don''t usually like cat shots, but this is a really great one.  The detail and focus are amazing.', '2003-10-21 09:34:48.000000', NULL, 1),
(456678, 42383, 10985, '<td valign="top">The light is exquisite here. Unfortunately, the focus is a little soft. Great sky!</td>', 'The light is exquisite here. Unfortunately, the focus is a little soft. Great sky!', '2003-10-21 09:47:24.000000', NULL, 1),
(456680, 42759, 10985, '<td valign="top">I love the backlight on the feather. Nice composition with the black and white bg.</td>', 'I love the backlight on the feather. Nice composition with the black and white bg.', '2003-10-21 09:49:48.000000', NULL, 1),
(456683, 42788, 5728, '<td valign="top">Very good, love the green glow on the letters. Kind of reminds me of the colors in "Godzilla" The black background highlights your letters even more, yassir, way to go!</td>', 'Very good, love the green glow on the letters. Kind of reminds me of the colors in "Godzilla" The black background highlights your letters even more, yassir, way to go!', '2003-10-21 09:56:15.000000', NULL, 1),
(456685, 42693, 5728, '<td valign="top">Good one, the effect of the rain is very image enhancing. Or did you use a super long shutter speed and those are stars? You have quite a few different light sources I see - 9.</td>', 'Good one, the effect of the rain is very image enhancing. Or did you use a super long shutter speed and those are stars? You have quite a few different light sources I see - 9.', '2003-10-21 09:59:08.000000', NULL, 1),
(456686, 42607, 5728, '<td valign="top">One word: simple, sharp and a bang on composition. One score: (9) :-)</td>', 'One word: simple, sharp and a bang on composition. One score: (9) :-)', '2003-10-21 10:00:31.000000', NULL, 1),
(456692, 42982, 12857, '<td valign="top">I love the way the light reflects off the vail.!!!  Nice shot<br/></td>', 'I love the way the light reflects off the vail.!!!  Nice shot', '2003-10-21 10:19:53.000000', NULL, 1),
(456693, 42503, 12857, '<td valign="top">Nice use of the rule of thirds.   Great capture!.</td>', 'Nice use of the rule of thirds.   Great capture!.', '2003-10-21 10:21:35.000000', NULL, 1),
(456695, 42701, 12857, '<td valign="top">I like this one.  It reminds me of late night sleep over parties when I was a kid.  Great use of light!</td>', 'I like this one.  It reminds me of late night sleep over parties when I was a kid.  Great use of light!', '2003-10-21 10:22:43.000000', NULL, 1),
(456697, 42161, 11155, '<td valign="top">Face is overexposed.  I know this is a ''lighting'' challenge, but in this case, the overexposure washes out any detail.  The lighting also doesn''t "set the mood" for the image, either, which is also part of this challenge.  Noise on bottom of image.  I do like the fact that the face fills the frame, and the eyes have nice catch lights in them.  Model is attractive subject.</td>', 'Face is overexposed.  I know this is a ''lighting'' challenge, but in this case, the overexposure washes out any detail.  The lighting also doesn''t "set the mood" for the image, either, which is also part of this challenge.  Noise on bottom of image.  I do like the fact that the face fills the frame, and the eyes have nice catch lights in them.  Model is attractive subject.', '2003-10-21 10:23:22.000000', NULL, 1),
(456698, 42954, 12857, '<td valign="top">Not everone gets to take shots like this.  Great capture!</td>', 'Not everone gets to take shots like this.  Great capture!', '2003-10-21 10:23:29.000000', NULL, 1),
(456701, 42960, 12857, '<td valign="top">Nice capture.  Love the choice of BW. Finally someone put a glass on end.  It leaves me wondering what happend here!?<br/></td>', 'Nice capture.  Love the choice of BW. Finally someone put a glass on end.  It leaves me wondering what happend here!?', '2003-10-21 10:26:33.000000', NULL, 1),
(456702, 42963, 12857, '<td valign="top">Great color.  I love the scale of the dog in the photo.  It allows the viewer some room for discovery!! 8</td>', 'Great color.  I love the scale of the dog in the photo.  It allows the viewer some room for discovery!! 8', '2003-10-21 10:28:40.000000', NULL, 1),
(456704, 42992, 11155, '<td valign="top">I like the composition and the lighting adds almost an eerie feeling to this photo, at least for me.  Structure is interesting and the lighting complements it.</td>', 'I like the composition and the lighting adds almost an eerie feeling to this photo, at least for me.  Structure is interesting and the lighting complements it.', '2003-10-21 10:31:28.000000', NULL, 1),
(456705, 42087, 12857, '<td valign="top">Love this shot.  It took some time to wrap my brain around it.  Great use of light.  Photos that allow me to see an ordinary object in a new way are what photography is about.   I dont know if you planed it or not but the stem casts  a shadow perfectly parallel to the other shadows.  Great job.  8</td>', 'Love this shot.  It took some time to wrap my brain around it.  Great use of light.  Photos that allow me to see an ordinary object in a new way are what photography is about.   I dont know if you planed it or not but the stem casts  a shadow perfectly parallel to the other shadows.  Great job.  8', '2003-10-21 10:32:03.000000', NULL, 1),
