(456722, 42969, 12857, '<td valign="top">Great capture.  Great colors.  Beautiful  gradation of color.  The shadowing is perfect!! 8</td>', 'Great capture.  Great colors.  Beautiful  gradation of color.  The shadowing is perfect!! 8', '2003-10-21 10:52:56.000000', NULL, 1),
(456726, 42207, 7687, '<td valign="top">Interesting background you have going on here, two different light sources?  Good exposure on the vase, perfect.  This vase has some very interesting texture, which, in combination with a different light source could yeild some interesting shadows.</td>', 'Interesting background you have going on here, two different light sources?  Good exposure on the vase, perfect.  This vase has some very interesting texture, which, in combination with a different light source could yeild some interesting shadows.', '2003-10-21 11:00:42.000000', NULL, 1),
