(460190, 42843, 5176, '<td valign="top">excellent picture maybe a tigher crop to lose the road/path and show more detail of the model ? 9</td>', 'excellent picture maybe a tigher crop to lose the road/path and show more detail of the model ? 9', '2003-10-23 15:13:10.000000', NULL, 1),
(460239, 43002, 7778, '<td valign="top">Very traditional image likely appealing to a broad spectrum of viewers, technically accomplished and sensitively executed.<br/> <br/>Critical notes: Such a warm and -soft- rendition would, IMHO, benefit from a complete absence of any decor. I''d prefer a hairline border, white or black or none or at all. The hue-matched line, I feel, softens an already soft image.<br/> <br/>The tilt of the vase is weighted heavily by the spatial extension of the single grass across the width of the photo. For a more pedantically balanced composition, I feel, that a slight counter-clockwise rotation would be something I''d consider.<br/> <br/></td>', 'Very traditional image likely appealing to a broad spectrum of viewers, technically accomplished and sensitively executed. Critical notes: Such a warm and -soft- rendition would, IMHO, benefit from a complete absence of any decor. I''d prefer a hairline border, white or black or none or at all. The hue-matched line, I feel, softens an already soft image. The tilt of the vase is weighted heavily by the spatial extension of the single grass across the width of the photo. For a more pedantically balanced composition, I feel, that a slight counter-clockwise rotation would be something I''d consider. ', '2003-10-23 16:21:37.000000', NULL, 1),
(460260, 42995, 5112, '<td valign="top">Beautiful!</td>', 'Beautiful!', '2003-10-23 16:52:42.000000', NULL, 1),
