(461589, 42805, 5767, '<td valign="top">Nice use of light.  Beautiful driftwood.  Might be too simple to get really high marks, but I enjoyed the form here.</td>', 'Nice use of light.  Beautiful driftwood.  Might be too simple to get really high marks, but I enjoyed the form here.', '2003-10-25 02:57:54.000000', NULL, 1),
(461590, 43012, 5767, '<td valign="top">I liked this one.  Funny and creative.</td>', 'I liked this one.  Funny and creative.', '2003-10-25 03:00:14.000000', NULL, 1),
(461591, 42987, 5767, '<td valign="top">This is a fun image in many ways.  Maybe too overexposed in the popcorn areas - all detail lost and it might have been good to at least have a hint of detail.</td>', 'This is a fun image in many ways.  Maybe too overexposed in the popcorn areas - all detail lost and it might have been good to at least have a hint of detail.', '2003-10-25 03:04:53.000000', NULL, 1),
