(461829, 42759, 8637, '<td valign="top">well done</td>', 'well done', '2003-10-25 18:40:04.000000', NULL, 1),
(461830, 42846, 8637, '<td valign="top">Nice colors and effect...lighting seems a little wrong though if the candle is the source since the light behind the bottle and shadows indicate other (less romantic?) lighting.  Well composed.</td>', 'Nice colors and effect...lighting seems a little wrong though if the candle is the source since the light behind the bottle and shadows indicate other (less romantic?) lighting.  Well composed.', '2003-10-25 18:41:53.000000', NULL, 1),
(461838, 42434, 527, '<td valign="top">This is a very nice photo but one thing that I would have done is move the horizon line down consideably to about 1/5 or 1/6 from the bottom. There is just too much black that distracts from the beautiful sky. Your exposure is vey good as is the details and colors. Score 8   Tim</td>', 'This is a very nice photo but one thing that I would have done is move the horizon line down consideably to about 1/5 or 1/6 from the bottom. There is just too much black that distracts from the beautiful sky. Your exposure is vey good as is the details and colors. Score 8   Tim', '2003-10-25 19:06:27.000000', NULL, 1),
(461984, 42958, 6668, '<td valign="top">Love the lighting in this shot...really helps give the feeling of rage. 9</td>', 'Love the lighting in this shot...really helps give the feeling of rage. 9', '2003-10-25 23:14:23.000000', NULL, 1),
