(462337, 42882, 10883, '<td valign="top">Very good framing and good colors from the sunset/sunrise.</td>', 'Very good framing and good colors from the sunset/sunrise.', '2003-10-26 13:37:47.000000', NULL, 1),
(462339, 42693, 1031, '<td valign="top">Looks like an effective time-exposure ... are those streaked clouds or aurora effects?</td>', 'Looks like an effective time-exposure ... are those streaked clouds or aurora effects?', '2003-10-26 13:38:21.000000', NULL, 1),
(462340, 42846, 10883, '<td valign="top">Nice setup but the lighting is a bit bland.  It would maybe be better to use a bit softer lighting and use it to highlight the reds in the red wine glasses.</td>', 'Nice setup but the lighting is a bit bland.  It would maybe be better to use a bit softer lighting and use it to highlight the reds in the red wine glasses.', '2003-10-26 13:39:16.000000', NULL, 1),
