(462710, 42846, 6651, '<td valign="top">Wonder how romantic this would look with the lights out?</td>', 'Wonder how romantic this would look with the lights out?', '2003-10-26 21:23:19.000000', NULL, 1),
(462721, 42916, 7504, '<td valign="top">The subject here seems out of focus, but the rocks and water are very clear, perhaps this was intentional.  I do like the effect used here.</td>', 'The subject here seems out of focus, but the rocks and water are very clear, perhaps this was intentional.  I do like the effect used here.', '2003-10-26 21:35:34.000000', NULL, 1),
(462723, 42770, 7504, '<td valign="top">I''m not sure what the little lights in the lower left hand corner are for, but the pumpkin itself is perfectly in focus and well-done.</td>', 'I''m not sure what the little lights in the lower left hand corner are for, but the pumpkin itself is perfectly in focus and well-done.', '2003-10-26 21:36:44.000000', NULL, 1),
(462724, 42887, 7504, '<td valign="top">I really like this, the mood, the tones, the whole feel of the piece.  Nice job.</td>', 'I really like this, the mood, the tones, the whole feel of the piece.  Nice job.', '2003-10-26 21:40:01.000000', NULL, 1),
(462725, 42958, 7504, '<td valign="top">Good halloween shot!  I love the red lighting in this.</td>', 'Good halloween shot!  I love the red lighting in this.', '2003-10-26 21:40:28.000000', NULL, 1),
(462735, 42503, 7485, '<td valign="top">Great composition, just not quite dark enough</td>', 'Great composition, just not quite dark enough', '2003-10-26 22:25:05.000000', NULL, 1),
(462746, 42916, 7038, '<td valign="top">I really like this shot a lot, I like the slight soft focus used here on the boy and i think the desturation technique works well here to draw your attention to the subject ( I wonder how it would lok in colour though).  The only small adjustment  (if possible) would be to leave a little more room on the bottom of the shot, below the foot.  kind of leave the impression of the foot dangling over the edge, and the tip of the stick rippling in the water.  9</td>', 'I really like this shot a lot, I like the slight soft focus used here on the boy and i think the desturation technique works well here to draw your attention to the subject ( I wonder how it would lok in colour though).  The only small adjustment  (if possible) would be to leave a little more room on the bottom of the shot, below the foot.  kind of leave the impression of the foot dangling over the edge, and the tip of the stick rippling in the water.  9', '2003-10-26 22:53:39.000000', NULL, 1),
(462748, 42539, 7038, '<td valign="top">A very visually appealing photo.   The lighting and use of colours here are very pleasing to the eye and makes the picture very easy to look at as my eye stays on the shot for some time.  8</td>', 'A very visually appealing photo.   The lighting and use of colours here are very pleasing to the eye and makes the picture very easy to look at as my eye stays on the shot for some time.  8', '2003-10-26 22:55:14.000000', NULL, 1),
(462752, 42685, 7038, '<td valign="top">Very nice picture.  I think the grain works well here as does the harsh lighting.  My suggestion would be though to crop of an inch or two from the bottom as there is nothing below the feet and the uneven floor and floor boards draw the eye away from the main subject. 7</td>', 'Very nice picture.  I think the grain works well here as does the harsh lighting.  My suggestion would be though to crop of an inch or two from the bottom as there is nothing below the feet and the uneven floor and floor boards draw the eye away from the main subject. 7', '2003-10-26 22:57:57.000000', NULL, 1),
(462757, 42719, 4805, '<td valign="top">This is one of my favourites in the challenge. Great lighting, great pose. I like the black eyes...they really add to the musicbox ballerina effect. I hope you do well.</td>', 'This is one of my favourites in the challenge. Great lighting, great pose. I like the black eyes...they really add to the musicbox ballerina effect. I hope you do well.', '2003-10-26 23:02:22.000000', NULL, 1),
(462758, 42410, 7038, '<td valign="top">I''m not sure exactly what kind of effect you are going for here, but this photo really doesn''t do much for me..</td>', 'I''m not sure exactly what kind of effect you are going for here, but this photo really doesn''t do much for me..', '2003-10-26 23:02:49.000000', NULL, 1),
(462768, 42997, 10263, '<td valign="top">I love the dreamy, lost-in-the-fire look in the younger ones eyes. Excellent shot. Great lighting.</td>', 'I love the dreamy, lost-in-the-fire look in the younger ones eyes. Excellent shot. Great lighting.', '2003-10-26 23:16:55.000000', NULL, 1),
